input.command:

export SSH_KEY=$(cat /home/runner/.ssh/authorized_keys)

echo "Testing public-key login as runner user:"
ssh -o BatchMode=yes -o PreferredAuthentications=publickey -o StrictHostKeyChecking=no -o ConnectTimeout=5 root@localhost <<< "$SSH_KEY" 2>&1 && echo "SUCCESS: Login as root via public key works" || echo "FAILED: Login as root via public key"
